-- Independent PTF database holdout, frozen proposal plus approved waiver/media amendments.
-- No visible PTF suite, PTF implementation or proposed migration was read.
-- Serial lock observations are not evidence of competing-connection race outcomes.
begin;
set local role postgres;
set local search_path to public,extensions;
select plan(290);
create function pg_temp.u(n integer)returns uuid language sql immutable as $$select('73900000-0000-4000-8000-'||lpad(to_hex(n),12,'0'))::uuid$$;
create function pg_temp.sc(n integer default 1)returns text language sql as $$select jsonb_build_object('sub',pg_temp.u(200+n),'role','authenticated','tenant_id',pg_temp.u(case when n=6 then 2 else 1 end),'staff_id',pg_temp.u(200+n),'app_role',case n when 1 then 'gym_owner'when 2 then 'gym_manager'when 3 then 'front_desk'when 6 then 'gym_owner'else 'trainer'end)::text$$;
create function pg_temp.mc(n integer default 100)returns text language sql as $$select jsonb_build_object('sub',pg_temp.u(1000+n),'role','authenticated','tenant_id',pg_temp.u(case when n=108 then 2 else 1 end),'member_id',pg_temp.u(n),'app_role','member')::text$$;
create function pg_temp.run(q text,c text default pg_temp.sc(),r text default 'authenticated')returns jsonb language plpgsql as $$declare v jsonb;d text;begin perform set_config('request.jwt.claims',coalesce(c,''),true);execute format('set local role %I',r);begin execute q into v;exception when others then get stacked diagnostics d=pg_exception_detail;v:=jsonb_build_object('error',sqlstate,'detail',d);end;set local role postgres;perform set_config('request.jwt.claims','',true);return coalesce(v,'null'::jsonb);end$$;
create temp table h73_res(k text primary key,v jsonb);
grant select on h73_res to authenticated;
create function pg_temp.ord(k text)returns uuid language sql as $$select(v->>'order_id')::uuid from h73_res where h73_res.k=$1$$;
create function pg_temp.sid(k text)returns uuid language sql as $$select(v->>'initial_session_id')::uuid from h73_res where h73_res.k=$1$$;
