insert into public.members(id,user_id,tenant_id,branch_id,full_name,phone,date_of_birth,status)select pg_temp.u(n),pg_temp.u(1000+n),pg_temp.u(case when n=108 then 2 else 1 end),pg_temp.u(case when n=108 then 21 else 11 end),'PT PRIVATE member '||n,'+919739'||lpad(n::text,6,'0'),date '1990-01-01',case when n=105 then 'blocked'::public.member_status when n=106 then 'cancelled'::public.member_status else 'active'::public.member_status end from generate_series(100,108)n;
