create function pg_temp.sale(k text,product integer default 600,member integer default 100,offset_hours integer default 3)returns jsonb language plpgsql as $$declare v jsonb;begin v:=pg_temp.run(format('select to_jsonb(r)from public.record_addon_sale(%L,%L,1,(select quote_version from public.addon_products where id=%L),%L,%L,%L,''cash'',''PT holdout sale'',%L)r',pg_temp.u(member),pg_temp.u(product),pg_temp.u(product),pg_temp.u(case when product=604 then 205 else 204 end),(date_trunc('hour',statement_timestamp()at time zone 'Asia/Kolkata')at time zone 'Asia/Kolkata')+offset_hours*interval '1 hour',(date_trunc('hour',statement_timestamp()at time zone 'Asia/Kolkata')at time zone 'Asia/Kolkata')+(offset_hours+1)*interval '1 hour',pg_temp.u(10000+offset_hours)));insert into h73_res values(k,v);return v;end$$;
