v:=pg_temp.run(format('select to_jsonb(r)from public.record_addon_sale(%L,%L,1,(select quote_version from public.addon_products where id=%L),%L,%L,%L,''cash'',''Boundary sale'',%L)r',pg_temp.u(100),pg_temp.u(601),pg_temp.u(601),pg_temp.u(204),statement_timestamp()+interval '24 hours'+delta,statement_timestamp()+interval '25 hours'+delta,pg_temp.u(key_n)));
if v?'error'then return v;end if;insert into h73_res values('cutoff'||key_n,v);return pg_temp.run(format('select to_jsonb(r)from public.cancel_pt_booking(%L)r',(v->>'initial_session_id')::uuid),pg_temp.mc());end$$;
